import {
  ApiKeyAccessConfig,
  ModelConfig,
  ProviderConfig,
  ProviderConfigMap,
  ProviderTemplateMap,
  resolveProviderTemplateName,
  type ModelConfigRules,
  type ModelId,
  type ProviderConfigRule,
  type ProviderId,
  type ProviderTemplateId,
  type ProviderTemplateLocale,
} from "./config/index.js";
import type { ModelSelection } from "@knorvia/shared/model-selection";
import { resolveOwnedOrder } from "./owned-order.js";
import type { ProviderConfigSnapshot, ProviderSource } from "./sources.js";

export interface ProviderConfigLayerSnapshot {
  readonly revision: string;
  readonly providers: ProviderConfigMap;
  readonly providerTemplates?: ProviderTemplateMap;
  readonly models: ModelConfigRules;
  readonly providerOrder?: readonly ProviderId[];
  readonly defaultModelSelection?: ModelSelection;
}

export interface ProviderConfigLayerUpdate {
  readonly providers: ProviderConfigMap;
  readonly providerTemplates?: ProviderTemplateMap;
  readonly models: ModelConfigRules;
  readonly providerOrder?: readonly ProviderId[];
  readonly defaultModelSelection?: ModelSelection;
}

export interface PersonalProviderConfigRepository
  extends ProviderSource<ProviderConfigLayerSnapshot> {
  update(
    transform: (current: ProviderConfigLayerSnapshot) => ProviderConfigLayerUpdate,
  ): Promise<ProviderConfigLayerSnapshot>;
}

export interface ProviderConfigServiceDependencies {
  readonly knorviaBuiltinSource: ProviderSource<ProviderConfigLayerSnapshot>;
  readonly personalRepository: PersonalProviderConfigRepository;
}

export interface PersonalProviderCreation {
  readonly providerId: ProviderId;
}

export interface CreatePersonalProviderInput {
  readonly templateId?: ProviderTemplateId;
  readonly providerName?: string;
  readonly locale?: ProviderTemplateLocale;
  readonly initialConfig?: ProviderConfig;
}

export interface ProviderModelMembership {
  readonly providerId: ProviderId;
  readonly inheritedModelIds: readonly ModelId[];
  readonly personalRevision: string;
  readonly assertCurrent: () => void;
}

function requireId(value: string, label: "providerId" | "modelId"): string {
  const trimmed = value.trim();
  if (!trimmed) throw new Error(`${label} 不能为空`);
  return trimmed;
}

function assertMembership(
  membership: ProviderModelMembership | undefined,
  providerId: ProviderId,
  current: ProviderConfigLayerSnapshot,
): void {
  if (!membership) return;
  membership.assertCurrent();
  if (
    membership.providerId !== providerId ||
    membership.personalRevision !== current.revision
  ) {
    throw new Error("Provider Settings membership revision conflict");
  }
}

function providerBaseline(
  providerId: ProviderId,
  builtin: ProviderConfigLayerSnapshot,
  current: ProviderConfigLayerSnapshot,
): ProviderConfig | undefined {
  const exact = builtin.providers.get(providerId);
  if (exact) return exact;
  return currentTemplateConfig(providerId, builtin, current);
}

function currentTemplateConfig(
  providerId: ProviderId,
  builtin: ProviderConfigLayerSnapshot,
  current: ProviderConfigLayerSnapshot,
): ProviderConfig | undefined {
  const templateId = current.providers.getRule(providerId)?.templateId;
  return templateId
    ? builtin.providerTemplates?.get(templateId)?.config
    : undefined;
}

function inheritedModels(
  providerId: ProviderId,
  builtin: ProviderConfigLayerSnapshot,
  current: ProviderConfigLayerSnapshot,
  membership: ProviderModelMembership | undefined,
): readonly ModelId[] {
  return (
    membership?.inheritedModelIds ??
    builtin.providers.get(providerId)?.builtinModelIds ??
    currentTemplateConfig(providerId, builtin, current)?.builtinModelIds ??
    []
  );
}

function writableProvider(
  providerId: ProviderId,
  builtin: ProviderConfigLayerSnapshot,
  current: ProviderConfigLayerSnapshot,
): ProviderConfig {
  const personal = current.providers.get(providerId);
  if (personal) return personal;
  if (builtin.providers.has(providerId)) return new ProviderConfig({});
  throw new Error(`Provider 不存在: ${providerId}`);
}

function modelOrder(
  inherited: readonly ModelId[],
  personal: readonly ModelId[],
  requested: readonly ModelId[],
): ModelId[] {
  return [...resolveOwnedOrder(inherited, personal, requested)];
}

function personalProviderIds(providers: ProviderConfigMap): ProviderId[] {
  return providers
    .entries()
    .filter(([, config]) => config.group === "standard-personal")
    .map(([id]) => id);
}

function providerOrder(
  providers: ProviderConfigMap,
  requested: readonly ProviderId[],
): ProviderId[] {
  return [...resolveOwnedOrder([], personalProviderIds(providers), requested)];
}

function labelFor(providers: ProviderConfigMap, providerId: ProviderId): string {
  return providers.getRule(providerId)?.providerName ?? "";
}

function labelKey(label: string): string {
  return label.trim().toLocaleLowerCase();
}

function uniqueId(base: string, occupied: ReadonlySet<string>): string {
  let candidate = base;
  for (let suffix = 2; occupied.has(candidate); suffix += 1) {
    candidate = `${base}-${suffix}`;
  }
  return candidate;
}

function uniqueLabel(base: string, occupied: ReadonlySet<string>): string {
  let candidate = base;
  for (let suffix = 2; occupied.has(labelKey(candidate)); suffix += 1) {
    candidate = `${base} ${suffix}`;
  }
  return candidate;
}

function structurallyEmpty(value: unknown): boolean {
  if (value === undefined) return true;
  if (value === null || typeof value !== "object") return false;
  if (Array.isArray(value)) return value.length === 0;
  return Object.values(value).every(structurallyEmpty);
}

function renameMembership(
  provider: ProviderConfig,
  inherited: readonly ModelId[],
  originalId: ModelId,
  nextId: ModelId,
): ProviderConfig {
  const personal = (provider.personalModelIds ?? []).map((id) =>
    id === originalId ? nextId : id,
  );
  const requested = (provider.modelOrder ?? []).map((id) =>
    id === originalId ? nextId : id,
  );
  return provider
    .withPersonalModelIds(personal)
    .withModelOrder(modelOrder(inherited, personal, requested));
}

export class ProviderConfigService
  implements ProviderSource<ProviderConfigSnapshot> {
  readonly #knorviaBuiltinSource: ProviderSource<ProviderConfigLayerSnapshot>;
  readonly #personalRepository: PersonalProviderConfigRepository;
  readonly #listeners = new Set<(reason: string) => void>();
  readonly #subscriptionDisposers: Array<() => void> = [];
  #disposed = false;

  constructor(dependencies: ProviderConfigServiceDependencies) {
    this.#knorviaBuiltinSource = dependencies.knorviaBuiltinSource;
    this.#personalRepository = dependencies.personalRepository;
    this.#subscriptionDisposers.push(
      this.#knorviaBuiltinSource.onDidChange((reason) =>
        this.#emitChange(`knorviaBuiltin:${reason}`),
      ),
    );
    this.#subscriptionDisposers.push(
      this.#personalRepository.onDidChange((reason) =>
        this.#emitChange(`personal:${reason}`),
      ),
    );
  }

  async read(): Promise<ProviderConfigSnapshot> {
    this.#assertActive();
    const [builtin, personal] = await Promise.all([
      this.#knorviaBuiltinSource.read(),
      this.#personalRepository.read(),
    ]);
    return Object.freeze({
      revision: JSON.stringify([builtin.revision, personal.revision]),
      knorviaBuiltinRevision: builtin.revision,
      personalRevision: personal.revision,
      knorviaBuiltinProviders: builtin.providers,
      knorviaBuiltinProviderTemplates:
        builtin.providerTemplates ?? ProviderTemplateMap.empty(),
      personalProviders: personal.providers,
      knorviaBuiltinModelRules: builtin.models,
      personalModels: personal.models,
      personalProviderOrder: personal.providerOrder ?? [],
    });
  }

  onDidChange(listener: (reason: string) => void): () => void {
    this.#assertActive();
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  replacePersonalConfig(
    config: ProviderConfigLayerUpdate,
  ): Promise<ProviderConfigLayerSnapshot> {
    this.#assertActive();
    return this.#personalRepository.update(() => config);
  }

  async savePersonalProviderOverlay(
    providerId: ProviderId,
    config: ProviderConfig,
    membership?: ProviderModelMembership,
    metadata?: Pick<ProviderConfigRule, "providerName" | "templateId" | "enabled">,
  ): Promise<ProviderConfigLayerSnapshot> {
    requireId(providerId, "providerId");
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const builtinProvider = builtin.providers.get(providerId);
      const currentPersonal = current.providers.get(providerId);
      const effective = builtin.providers.overlay(current.providers);
      if (
        builtinProvider?.access?.type === "zhipu-account" &&
        metadata?.enabled === false
      ) {
        throw new Error(`Account Provider 不允许禁用: ${providerId}`);
      }
      if (
        builtinProvider?.access?.type === "zhipu-account" &&
        config.access !== undefined
      ) {
        throw new Error(
          `固定 Account Provider 的 Access 只能由 Knorvia Studio Built-in Config 声明: ${providerId}`,
        );
      }
      if (!currentPersonal && !builtinProvider) {
        throw new Error(`Personal Provider 尚未创建: ${providerId}`);
      }

      let suppliedConfig: ProviderConfig;
      if (builtinProvider) {
        if (config.group != null && config.group !== builtinProvider.group) {
          throw new Error(
            `Personal Overlay 不能改写 Built-in Provider group: ${providerId}`,
          );
        }
        suppliedConfig = config.withoutGroup();
      } else {
        const group = config.group ?? currentPersonal?.group;
        if (group !== "standard-personal") {
          throw new Error(
            `Personal-only Provider 必须使用 standard-personal group: ${providerId}`,
          );
        }
        suppliedConfig = config.overlay(new ProviderConfig({ group }));
      }

      let normalizedMembership = currentPersonal;
      if (currentPersonal) {
        const inherited = [
          ...new Set(
            membership?.inheritedModelIds ??
            providerBaseline(providerId, builtin, current)?.builtinModelIds ??
            [],
          ),
        ];
        const inheritedSet = new Set(inherited);
        const personal = [...new Set(currentPersonal.personalModelIds ?? [])]
          .filter((id) => !inheritedSet.has(id));
        normalizedMembership = currentPersonal.withPersonalModelIds(personal);
        if (currentPersonal.modelOrder != null) {
          normalizedMembership = normalizedMembership.withModelOrder(
            modelOrder(inherited, personal, currentPersonal.modelOrder),
          );
        }
      }
      const nextRule: ProviderConfigRule = {
        ...current.providers.getRule(providerId),
        providerId,
        ...(metadata?.templateId !== undefined
          ? { templateId: metadata.templateId }
          : {}),
        ...(metadata?.enabled !== undefined
          ? { enabled: metadata.enabled }
          : {}),
        ...(metadata?.providerName !== undefined
          ? { providerName: metadata.providerName?.trim() || null }
          : {}),
        config: suppliedConfig.withModelMembershipFrom(normalizedMembership),
      };
      const providers = current.providers.setRule(nextRule);
      const nextEffective = builtin.providers.overlay(providers);
      const currentKey = labelKey(labelFor(effective, providerId));
      const nextLabel = labelFor(nextEffective, providerId).trim();
      const nextKey = nextLabel.toLocaleLowerCase();
      if (nextKey && nextKey !== currentKey) {
        for (const otherId of nextEffective.keys()) {
          if (
            otherId !== providerId &&
            labelKey(labelFor(nextEffective, otherId)) === nextKey
          ) {
            throw new Error(`Provider 名称已存在: ${nextLabel}`);
          }
        }
      }
      return {
        providers,
        models: current.models,
        providerOrder: current.providerOrder,
      };
    });
  }

  async createPersonalProvider(
    input: CreatePersonalProviderInput = {},
  ): Promise<PersonalProviderCreation> {
    const builtin = await this.#knorviaBuiltinSource.read();
    const templateId = input.templateId?.trim();
    const template = templateId
      ? builtin.providerTemplates?.get(templateId)
      : undefined;
    if (templateId && !template) {
      throw new Error(`Provider Template 不存在: ${templateId}`);
    }
    if (input.initialConfig?.group !== undefined) {
      throw new Error("initialConfig 不能包含 group");
    }
    if (input.initialConfig?.builtinModelIds !== undefined) {
      throw new Error("initialConfig 不能包含 builtinModelIds");
    }
    let createdId: ProviderId | undefined;
    await this.#update((current) => {
      const idSeed = templateId
        ? templateId.trim().toLocaleLowerCase()
          .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "new-provider"
        : "new-provider";
      const providerId = uniqueId(
        idSeed,
        new Set([...builtin.providers.keys(), ...current.providers.keys()]),
      );
      const seed = (
        input.providerName ??
        (template && templateId
          ? resolveProviderTemplateName(
            templateId, template, input.locale ?? "en-US",
          )
          : "new-provider")
      ).trim() || "new-provider";
      const templatedPersonal = current.providers.mapConfigs(
        (config, _id, rule) => {
          const templateConfig = rule.templateId
            ? builtin.providerTemplates?.get(rule.templateId)?.config
            : undefined;
          return templateConfig ? templateConfig.overlay(config) : config;
        },
      );
      const effective = builtin.providers.overlay(templatedPersonal);
      const providerName = uniqueLabel(
        seed,
        new Set(effective.keys().map((id) => labelKey(labelFor(effective, id)))),
      );
      const config = new ProviderConfig({
        group: "standard-personal",
        access: templateId ? undefined : new ApiKeyAccessConfig(),
        personalModelIds: [],
        modelOrder: [],
      }).overlay(input.initialConfig ?? new ProviderConfig());
      const providers = current.providers.setRule({
        providerId,
        ...(templateId ? { templateId } : {}),
        providerName,
        config,
      });
      const priorOrder = providerOrder(
        current.providers,
        current.providerOrder ?? [],
      ).filter((id) => id !== providerId);
      const nextOrder = providerOrder(providers, [...priorOrder, providerId]);
      createdId = providerId;
      return {
        providers,
        models: current.models,
        providerOrder: nextOrder,
      };
    });
    if (!createdId) throw new Error("Personal Provider 创建失败");
    return Object.freeze({ providerId: createdId });
  }

  deletePersonalProvider(
    providerId: ProviderId,
  ): Promise<ProviderConfigLayerSnapshot> {
    requireId(providerId, "providerId");
    return this.#update((current) => ({
      providers: current.providers.delete(providerId),
      models: current.models.deleteExactForProvider(providerId),
      providerOrder: current.providerOrder?.filter((id) => id !== providerId),
    }));
  }

  async reorderPersonalProviders(
    providerIds: readonly ProviderId[],
  ): Promise<ProviderConfigLayerSnapshot> {
    await this.#knorviaBuiltinSource.read();
    return this.#update((current) => ({
      providers: current.providers,
      models: current.models,
      providerOrder: providerOrder(current.providers, providerIds),
    }));
  }

  async reorderPersonalModels(
    providerId: ProviderId,
    modelIds: readonly ModelId[],
    membership?: ProviderModelMembership,
  ): Promise<ProviderConfigLayerSnapshot> {
    requireId(providerId, "providerId");
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const baseline = providerBaseline(providerId, builtin, current);
      const provider = writableProvider(providerId, builtin, current);
      const inherited = membership?.inheritedModelIds ??
        baseline?.builtinModelIds ?? [];
      return {
        providers: current.providers.set(
          providerId,
          provider.withModelOrder(
            modelOrder(inherited, provider.personalModelIds ?? [], modelIds),
          ),
        ),
        models: current.models,
        providerOrder: current.providerOrder,
      };
    });
  }

  async addPersonalModel(
    providerId: ProviderId,
    modelId: ModelId,
    config: ModelConfig,
    membership?: ProviderModelMembership,
    useRecommendedConfig?: boolean,
  ): Promise<ProviderConfigLayerSnapshot> {
    providerId = requireId(providerId, "providerId");
    modelId = requireId(modelId, "modelId");
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const provider = writableProvider(providerId, builtin, current);
      const inherited = inheritedModels(providerId, builtin, current, membership);
      const personal = provider.personalModelIds ?? [];
      if (inherited.includes(modelId)) {
        throw new Error(`Model 已存在: ${providerId}/${modelId}`);
      }
      if (personal.includes(modelId)) {
        throw new Error(`Model 已存在: ${providerId}/${modelId}`);
      }
      const nextPersonal = [...personal, modelId];
      const nextProvider = provider
        .withPersonalModelIds(nextPersonal)
        .withModelOrder(
          modelOrder(inherited, nextPersonal, provider.modelOrder ?? []),
        );
      return {
        providers: current.providers.set(providerId, nextProvider),
        models: current.models.setExact(
          providerId,
          modelId,
          config.overlay(new ModelConfig({ enabled: true })),
          useRecommendedConfig,
        ),
        providerOrder: current.providerOrder,
      };
    });
  }

  async renamePersonalModel(
    providerId: ProviderId,
    currentModelId: ModelId,
    nextModelId: ModelId,
    membership?: ProviderModelMembership,
  ): Promise<ProviderConfigLayerSnapshot> {
    providerId = requireId(providerId, "providerId");
    currentModelId = requireId(currentModelId, "modelId");
    nextModelId = requireId(nextModelId, "modelId");
    if (currentModelId === nextModelId) return this.#personalRepository.read();
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const inherited = inheritedModels(providerId, builtin, current, membership);
      const provider = current.providers.get(providerId);
      const personal = provider?.personalModelIds ?? [];
      if (inherited.includes(currentModelId)) {
        throw new Error(
          `Built-in Model 不能重命名: ${providerId}/${currentModelId}`,
        );
      }
      if (!provider || !personal.includes(currentModelId)) {
        throw new Error(
          `Personal Model 不存在: ${providerId}/${currentModelId}`,
        );
      }
      if (personal.includes(nextModelId)) {
        throw new Error(`Model 已存在: ${providerId}/${nextModelId}`);
      }
      if (inherited.includes(nextModelId)) {
        throw new Error(`Model 已存在: ${providerId}/${nextModelId}`);
      }
      return {
        providers: current.providers.set(
          providerId,
          renameMembership(provider, inherited, currentModelId, nextModelId),
        ),
        models: current.models.renameExactModel(
          providerId, currentModelId, nextModelId,
        ),
        providerOrder: current.providerOrder,
      };
    });
  }

  async setPersonalModelEnabled(
    providerId: ProviderId,
    modelId: ModelId,
    enabled: boolean,
    membership?: ProviderModelMembership,
  ): Promise<ProviderConfigLayerSnapshot> {
    providerId = requireId(providerId, "providerId");
    modelId = requireId(modelId, "modelId");
    if (typeof enabled !== "boolean") {
      throw new Error("Model enabled 必须是 boolean");
    }
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const inherited = inheritedModels(providerId, builtin, current, membership);
      const personal = current.providers.get(providerId)?.personalModelIds ?? [];
      if (!inherited.includes(modelId) && !personal.includes(modelId)) {
        throw new Error(`Model 不存在: ${providerId}/${modelId}`);
      }
      const config = current.models.getExact(providerId, modelId) ??
        new ModelConfig({});
      return {
        providers: current.providers,
        models: current.models.setExact(
          providerId,
          modelId,
          config.overlay(new ModelConfig({ enabled })),
        ),
        providerOrder: current.providerOrder,
      };
    });
  }

  async savePersonalModelDraft(
    providerId: ProviderId,
    originalModelId: ModelId,
    nextModelId: ModelId,
    config: ModelConfig,
    expectedPersonalRevision: string,
    useRecommendedConfig?: boolean,
    membership?: ProviderModelMembership,
  ): Promise<ProviderConfigLayerSnapshot> {
    providerId = requireId(providerId, "providerId");
    originalModelId = requireId(originalModelId, "modelId");
    nextModelId = requireId(nextModelId, "modelId");
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      if (current.revision !== expectedPersonalRevision) {
        throw new Error(
          `Personal Provider Config revision conflict: expected ${expectedPersonalRevision}, current ${current.revision}`,
        );
      }
      const recommended = useRecommendedConfig ??
        (current.models.getExactRule(providerId, originalModelId)?.type !==
          "manual-provider-model");
      const inherited = inheritedModels(providerId, builtin, current, membership);
      const provider = current.providers.get(providerId);
      const personal = provider?.personalModelIds ?? [];
      const renaming = originalModelId !== nextModelId;
      if (renaming && inherited.includes(originalModelId)) {
        throw new Error(
          `Built-in Model 不能重命名: ${providerId}/${originalModelId}`,
        );
      }
      if (renaming && inherited.includes(nextModelId)) {
        throw new Error(`Model 已存在: ${providerId}/${nextModelId}`);
      }
      if (!inherited.includes(originalModelId) && !personal.includes(originalModelId)) {
        throw new Error(`Model 不存在: ${providerId}/${originalModelId}`);
      }
      if (
        renaming &&
        (personal.includes(nextModelId) || inherited.includes(nextModelId))
      ) {
        throw new Error(`Model 已存在: ${providerId}/${nextModelId}`);
      }
      let providers = current.providers;
      let models = current.models;
      if (renaming) {
        if (!provider || !personal.includes(originalModelId)) {
          throw new Error(
            `Personal Model 不存在: ${providerId}/${originalModelId}`,
          );
        }
        providers = providers.set(
          providerId,
          renameMembership(provider, inherited, originalModelId, nextModelId),
        );
        models = models.renameExactModel(providerId, originalModelId, nextModelId);
      }
      models = recommended && structurallyEmpty(config.toJSON())
        ? models.deleteExact(providerId, nextModelId)
        : models.setExact(providerId, nextModelId, config, recommended);
      return {
        providers,
        models,
        providerOrder: current.providerOrder,
      };
    });
  }

  async deletePersonalModel(
    providerId: ProviderId,
    modelId: ModelId,
    membership?: ProviderModelMembership,
  ): Promise<ProviderConfigLayerSnapshot> {
    providerId = requireId(providerId, "providerId");
    modelId = requireId(modelId, "modelId");
    const builtin = await this.#knorviaBuiltinSource.read();
    return this.#update((current) => {
      assertMembership(membership, providerId, current);
      const inherited = inheritedModels(providerId, builtin, current, membership);
      if (inherited.includes(modelId)) {
        throw new Error(`Built-in Model 不能删除: ${providerId}/${modelId}`);
      }
      const provider = current.providers.get(providerId);
      const personal = provider?.personalModelIds ?? [];
      if (!provider || !personal.includes(modelId)) {
        throw new Error(`Personal Model 不存在: ${providerId}/${modelId}`);
      }
      const remaining = personal.filter((id) => id !== modelId);
      const nextProvider = provider
        .withPersonalModelIds(remaining)
        .withModelOrder(
          modelOrder(inherited, remaining, provider.modelOrder ?? []),
        );
      return {
        providers: current.providers.set(providerId, nextProvider),
        models: current.models.deleteExact(providerId, modelId),
        providerOrder: current.providerOrder,
      };
    });
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    for (const dispose of this.#subscriptionDisposers.splice(0)) dispose();
    this.#listeners.clear();
  }

  #assertActive(): void {
    if (this.#disposed) throw new Error("ProviderConfigService 已 dispose");
  }

  #emitChange(reason: string): void {
    if (this.#disposed) return;
    for (const listener of this.#listeners) listener(reason || "changed");
  }

  #update(
    transform: (current: ProviderConfigLayerSnapshot) => ProviderConfigLayerUpdate,
  ): Promise<ProviderConfigLayerSnapshot> {
    this.#assertActive();
    return this.#personalRepository.update((current) => ({
      defaultModelSelection: current.defaultModelSelection,
      ...transform(current),
    }));
  }
}
SOURCE_END
