import assert from "node:assert/strict";
import { test } from "node:test";
import { ProviderConfigService, type ProviderModelMembership } from "../src/config-service.js";
import {
  ModelConfig,
  ModelConfigRules,
  ProviderConfig,
  ProviderConfigMap,
  ProviderTemplate,
  ProviderTemplateMap,
  ZhipuAccountAccessConfig,
} from "../src/config/index.js";
import { deferred, FakePersonalRepository, FakeSource } from "./fake-owner-ports-20261003.js";
import type { ProviderConfigLayerSnapshot } from "../src/config-service.js";

test("synthetic config ports retain custom data, layered identity, owned order, atomic drafts/defaults and failure/disposal lifetime", async () => {
  const baseline = new ProviderConfig({
    group: "bigmodel-family",
    builtinModelIds: ["b1", "b2"],
  });
  const builtin = new FakeSource<ProviderConfigLayerSnapshot>({
    revision: "synthetic-builtin:1",
    providers: new ProviderConfigMap([
      { providerId: "builtin", providerName: "Builtin", config: baseline },
      { providerId: "empty-baseline", config: new ProviderConfig({ group: "bigmodel-family" }) },
      {
        providerId: "account",
        config: new ProviderConfig({ group: "zai-family", access: new ZhipuAccountAccessConfig() }),
      },
    ]),
    models: ModelConfigRules.empty(),
    providerTemplates: new ProviderTemplateMap([
      [
        "Template One",
        new ProviderTemplate({
          templateId: "Template One",
          templateNameMap: { "en-US": "Template Name" },
          config: new ProviderConfig({ builtinModelIds: ["t1"] }),
        }),
      ],
    ]),
  });
  const selection = Object.freeze({ providerId: "personal", modelId: "m1" });
  const repository = new FakePersonalRepository({
    revision: "synthetic-personal:0",
    providers: new ProviderConfigMap([
      {
        providerId: "empty-baseline",
        templateId: "Template One",
        config: new ProviderConfig({
          personalModelIds: ["t1", "keep"],
          modelOrder: ["t1", "keep"],
        }),
      },
      {
        providerId: "personal",
        providerName: "Custom",
        config: new ProviderConfig({
          group: "standard-personal",
          personalModelIds: ["m1"],
          modelOrder: ["m1"],
        }),
      },
    ]),
    models: ModelConfigRules.empty().setExact("personal", "m1", new ModelConfig({ enabled: true })),
    providerOrder: ["personal"],
    defaultModelSelection: selection,
  });
  const service = new ProviderConfigService({
    knorviaBuiltinSource: builtin,
    personalRepository: repository,
  });
  assert.deepEqual(Reflect.ownKeys(service), []);
  assert.deepEqual(
    Object.getOwnPropertyNames(ProviderConfigService.prototype).sort(),
    [
      "constructor",
      "read",
      "onDidChange",
      "replacePersonalConfig",
      "savePersonalProviderOverlay",
      "createPersonalProvider",
      "deletePersonalProvider",
      "reorderPersonalProviders",
      "reorderPersonalModels",
      "addPersonalModel",
      "renamePersonalModel",
      "setPersonalModelEnabled",
      "savePersonalModelDraft",
      "deletePersonalModel",
      "dispose",
    ].sort(),
  );
  const reasons: string[] = [];
  const remove = service.onDidChange((reason) => reasons.push(reason));
  builtin.emit("");
  repository.emit("synthetic");
  assert.deepEqual(reasons, ["knorviaBuiltin:", "personal:synthetic"]);
  const first = await service.read();
  assert.ok(Object.isFrozen(first));
  assert.equal(first.revision, '["synthetic-builtin:1","synthetic-personal:0"]');
  assert.equal(first.knorviaBuiltinProviders, builtin.snapshot.providers);
  assert.equal(first.personalProviders, repository.snapshot.providers);
  assert.equal(first.personalProviderOrder, repository.snapshot.providerOrder);
  assert.equal("defaultModelSelection" in first, false);

  const created = await service.createPersonalProvider();
  assert.deepEqual(created, { providerId: "new-provider" });
  assert.ok(Object.isFrozen(created));
  assert.equal(repository.snapshot.providers.get(created.providerId)?.access?.type, "api-key");
  const second = await service.createPersonalProvider({ providerName: " NEW-PROVIDER " });
  assert.equal(second.providerId, "new-provider-2");
  assert.equal(
    repository.snapshot.providers.getRule(second.providerId)?.providerName,
    "NEW-PROVIDER 2",
  );
  const fromTemplate = await service.createPersonalProvider({ templateId: " Template One " });
  assert.equal(fromTemplate.providerId, "template-one");
  assert.equal(repository.snapshot.providers.get(fromTemplate.providerId)?.access, undefined);
  assert.equal(
    repository.snapshot.providers.getRule(fromTemplate.providerId)?.providerName,
    "Template Name",
  );
  assert.equal(repository.snapshot.defaultModelSelection, selection);
  assert.deepEqual(repository.snapshot.providerOrder, [
    "personal",
    "new-provider",
    "new-provider-2",
    "template-one",
  ]);
  await service.reorderPersonalProviders(["unknown", "template-one", "personal", "personal"]);
  assert.deepEqual(repository.snapshot.providerOrder, [
    "template-one",
    "personal",
    "new-provider",
    "new-provider-2",
  ]);

  const unnamedIdLabel = await service.createPersonalProvider({ providerName: "account" });
  assert.equal(
    repository.snapshot.providers.getRule(unnamedIdLabel.providerId)?.providerName,
    "account",
  );
  await service.savePersonalProviderOverlay("empty-baseline", new ProviderConfig());
  assert.deepEqual(repository.snapshot.providers.get("empty-baseline")?.personalModelIds, [
    "t1",
    "keep",
  ]);
  await service.reorderPersonalModels("empty-baseline", ["keep"]);
  assert.deepEqual(repository.snapshot.providers.get("empty-baseline")?.modelOrder, ["keep", "t1"]);
  await assert.rejects(
    service.renamePersonalModel("empty-baseline", "t1", "renamed"),
    /Built-in Model 不能重命名/,
  );

  const member = (
    providerId: string,
    inheritedModelIds: readonly string[],
  ): ProviderModelMembership => ({
    providerId,
    inheritedModelIds,
    personalRevision: repository.snapshot.revision,
    assertCurrent: () => {},
  });
  await service.reorderPersonalModels("builtin", ["b2", "b1"]);
  await service.addPersonalModel(" builtin ", " x ", new ModelConfig({ enabled: false }));
  assert.deepEqual(repository.snapshot.providers.get("builtin")?.modelOrder, ["b2", "b1", "x"]);
  assert.equal(repository.snapshot.models.getExact("builtin", "x")?.enabled, true);
  await service.savePersonalProviderOverlay("builtin", new ProviderConfig(), member("builtin", []));
  assert.deepEqual(repository.snapshot.providers.get("builtin")?.personalModelIds, ["x"]);
  assert.deepEqual(repository.snapshot.providers.get("builtin")?.modelOrder, ["x"]);
  await service.reorderPersonalModels("template-one", ["t1"]);
  await service.addPersonalModel("template-one", "p1", new ModelConfig());
  assert.deepEqual(repository.snapshot.providers.get("template-one")?.modelOrder, ["t1", "p1"]);
  await assert.rejects(
    service.renamePersonalModel("template-one", "t1", "renamed"),
    /Built-in Model 不能重命名/,
  );
  await assert.rejects(
    service.deletePersonalModel("template-one", "t1"),
    /Built-in Model 不能删除/,
  );
  await service.renamePersonalModel("personal", "m1", "m2");
  assert.deepEqual(repository.snapshot.providers.get("personal")?.personalModelIds, ["m2"]);
  assert.equal(repository.snapshot.models.getExact("personal", "m1"), undefined);
  await service.savePersonalModelDraft(
    "personal",
    "m2",
    "m3",
    new ModelConfig(),
    repository.snapshot.revision,
    true,
  );
  assert.deepEqual(repository.snapshot.providers.get("personal")?.modelOrder, ["m3"]);
  assert.equal(repository.snapshot.models.getExact("personal", "m3"), undefined);
  const beforeRevisionFailure = repository.snapshot;
  await assert.rejects(
    service.savePersonalModelDraft("personal", "m3", "m4", new ModelConfig(), "synthetic-stale"),
    /revision conflict/,
  );
  assert.equal(repository.snapshot, beforeRevisionFailure);
  await service.savePersonalModelDraft(
    "personal",
    "m3",
    "m3",
    new ModelConfig({ properties: null }),
    repository.snapshot.revision,
    true,
  );
  assert.equal(repository.snapshot.models.getExact("personal", "m3")?.properties, null);
  await service.setPersonalModelEnabled("personal", "m3", false);
  assert.equal(repository.snapshot.models.getExact("personal", "m3")?.enabled, false);
  assert.equal(repository.snapshot.defaultModelSelection, selection);
  await service.deletePersonalModel("personal", "m3");
  assert.deepEqual(repository.snapshot.providers.get("personal")?.personalModelIds, []);
  await service.deletePersonalProvider("template-one");
  assert.equal(repository.snapshot.providers.has("template-one"), false);
  const beforeDeletedWrite = repository.snapshot;
  await assert.rejects(
    service.addPersonalModel("template-one", "late", new ModelConfig()),
    /Provider 不存在/,
  );
  await assert.rejects(
    service.savePersonalProviderOverlay("template-one", new ProviderConfig()),
    /尚未创建/,
  );
  assert.equal(repository.snapshot, beforeDeletedWrite);
  await assert.rejects(
    service.savePersonalProviderOverlay("account", new ProviderConfig(), undefined, {
      enabled: false,
    }),
    /Account Provider 不允许禁用/,
  );
  await assert.rejects(
    service.savePersonalProviderOverlay("account", new ProviderConfig({ access: null })),
    /Access 只能由/,
  );
  const exactFailure = new Error("synthetic repository failure");
  repository.updateFailure = exactFailure;
  await assert.rejects(
    service.reorderPersonalProviders([]),
    (error: unknown) => error === exactFailure,
  );
  assert.equal(repository.snapshot, beforeDeletedWrite);
  repository.updateFailure = undefined;
  const staleMembership = member("personal", []);
  await service.reorderPersonalProviders([]);
  const beforeStale = repository.snapshot;
  await assert.rejects(
    service.addPersonalModel("personal", "stale", new ModelConfig(), staleMembership),
    /membership revision conflict/,
  );
  assert.equal(repository.snapshot, beforeStale);
  const beforeLabelFailure = repository.snapshot;
  await assert.rejects(
    service.savePersonalProviderOverlay("personal", new ProviderConfig(), undefined, {
      providerName: "Builtin",
    }),
    /名称已存在/,
  );
  assert.equal(repository.snapshot, beforeLabelFailure);
  await service.savePersonalProviderOverlay("personal", new ProviderConfig(), undefined, {
    providerName: " Custom Renamed ",
  });
  assert.equal(repository.snapshot.providers.getRule("personal")?.providerName, "Custom Renamed");

  const metadataReads: string[] = [];
  await service.savePersonalProviderOverlay("personal", new ProviderConfig(), undefined, {
    get templateId() {
      metadataReads.push("templateId");
      return undefined;
    },
    get enabled() {
      metadataReads.push("enabled");
      return undefined;
    },
    get providerName() {
      metadataReads.push("providerName");
      return "  ";
    },
  });
  assert.deepEqual(metadataReads, ["templateId", "enabled", "providerName", "providerName"]);
  assert.equal(repository.snapshot.providers.getRule("personal")?.providerName, null);

  const replacement = {
    providers: repository.snapshot.providers,
    models: repository.snapshot.models,
  };
  await service.replacePersonalConfig(replacement);
  assert.equal(repository.updates.at(-1), replacement);
  assert.equal(repository.snapshot.defaultModelSelection, undefined);
  remove();
  const blockedRead = deferred<ProviderConfigLayerSnapshot>();
  builtin.readAction = () => blockedRead.promise;
  const reading = service.read();
  service.dispose();
  service.dispose();
  blockedRead.resolve(builtin.snapshot);
  assert.equal((await reading).knorviaBuiltinProviders, builtin.snapshot.providers);
  assert.equal(builtin.disposeCount, 1);
  assert.equal(repository.disposeCount, 1);
  assert.throws(() => service.onDidChange(() => {}), /ProviderConfigService 已 dispose/);
  await assert.rejects(service.read(), /ProviderConfigService 已 dispose/);
  assert.equal(await service.renamePersonalModel("personal", "same", "same"), repository.snapshot);
});

import type { ProviderSource } from "../src/sources.js";
import type {
  PersonalProviderConfigRepository,
  ProviderConfigLayerSnapshot,
  ProviderConfigLayerUpdate,
} from "../src/config-service.js";

export class FakeSource<T> implements ProviderSource<T> {
  readonly listeners = new Set<(reason: string) => void>();
  readCount = 0;
  subscribeCount = 0;
  disposeCount = 0;
  readAction: (() => Promise<T>) | undefined;
  disposeFailure: Error | undefined;
  constructor(public snapshot: T) {}
  read(): Promise<T> {
    this.readCount++;
    return this.readAction?.() ?? Promise.resolve(this.snapshot);
  }
  onDidChange(listener: (reason: string) => void): () => void {
    this.subscribeCount++;
    this.listeners.add(listener);
    return () => {
      this.disposeCount++;
      if (this.disposeFailure) throw this.disposeFailure;
      this.listeners.delete(listener);
    };
  }
  emit(reason: string): void {
    for (const listener of this.listeners) listener(reason);
  }
}

export class FakePersonalRepository
  extends FakeSource<ProviderConfigLayerSnapshot>
  implements PersonalProviderConfigRepository
{
  updateCount = 0;
  readonly updates: ProviderConfigLayerUpdate[] = [];
  updateFailure: Error | undefined;
  async update(
    transform: (current: ProviderConfigLayerSnapshot) => ProviderConfigLayerUpdate,
  ): Promise<ProviderConfigLayerSnapshot> {
    this.updateCount++;
    if (this.updateFailure) throw this.updateFailure;
    const next = transform(this.snapshot);
    this.updates.push(next);
    this.snapshot = Object.freeze({
      ...next,
      revision: `synthetic-personal:${this.updates.length}`,
    });
    this.emit("write");
    return this.snapshot;
  }
}

export function deferred<T>(): {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (error: unknown) => void;
} {
  let resolve!: (value: T) => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<T>((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return { promise, resolve, reject };
}

export async function flush(): Promise<void> {
  for (let step = 0; step < 20; step++) await Promise.resolve();
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { ProviderRegistryService } from "../src/registry-service.js";
import type {
  ProviderConfigResolver,
  ProviderConfigResolution,
  ProviderConfigResolverInput,
} from "../src/resolver.js";
import type { AccountProviderConfigSnapshot, ProviderConfigSnapshot } from "../src/sources.js";
import { ModelConfigRules, ProviderConfigMap, ProviderTemplateMap } from "../src/config/index.js";
import { deferred, FakeSource, flush } from "./fake-owner-ports-20261003.js";

function config(revision: string, builtinRevision = "synthetic-builtin:1"): ProviderConfigSnapshot {
  return {
    revision,
    knorviaBuiltinRevision: builtinRevision,
    personalRevision: "synthetic-personal:1",
    knorviaBuiltinProviders: ProviderConfigMap.empty(),
    knorviaBuiltinProviderTemplates: ProviderTemplateMap.empty(),
    personalProviders: ProviderConfigMap.empty(),
    knorviaBuiltinModelRules: ModelConfigRules.empty(),
    personalModels: ModelConfigRules.empty(),
    personalProviderOrder: [],
  };
}
function account(
  revision: string,
  builtinRevision = "synthetic-builtin:1",
): AccountProviderConfigSnapshot {
  return {
    revision,
    basedOnKnorviaBuiltinRevision: builtinRevision,
    providers: ProviderConfigMap.empty(),
    states: {},
  };
}

test("synthetic registry ports preserve consistency gating, source/snapshot identity, coalescing, native failure and cancellation lifetime", async () => {
  const marker = Object.freeze({ synthetic: true });
  const source = new FakeSource<ProviderConfigSnapshot>(
    Object.assign(config("synthetic-config:1"), { marker }),
  );
  const accounts = new FakeSource<AccountProviderConfigSnapshot>(
    Object.assign(account("synthetic-account:0", "synthetic-old"), { discarded: marker }),
  );
  const inputs: ProviderConfigResolverInput[] = [];
  const resolution: ProviderConfigResolution = {
    effectiveBuiltinProviders: ProviderConfigMap.empty(),
    effectiveProviders: ProviderConfigMap.empty(),
    resolvedProviders: [],
    registryProviders: [],
    issues: [],
  };
  let resolverFailure: Error | undefined;
  const resolver: ProviderConfigResolver = {
    resolve(input) {
      inputs.push(input);
      if (resolverFailure) throw resolverFailure;
      return resolution;
    },
  };
  const owner = new ProviderRegistryService({
    configSource: source,
    accountSource: accounts,
    resolver,
  });
  assert.deepEqual(Reflect.ownKeys(owner), []);
  assert.deepEqual(
    Object.getOwnPropertyNames(ProviderRegistryService.prototype).sort(),
    [
      "constructor",
      "start",
      "refresh",
      "getSnapshot",
      "getView",
      "listProviders",
      "getProvider",
      "getModel",
      "validateSelection",
      "onDidChange",
      "onDidRefreshError",
      "dispose",
    ].sort(),
  );
  assert.equal(owner.getSnapshot(), null);
  assert.equal(owner.getView().revision, 0);
  assert.equal(source.subscribeCount, 0);
  assert.throws(() => owner.refresh(), /必须先 start/);
  const changed: Array<{ reasons: readonly string[]; snapshot: unknown }> = [];
  const errors: Array<{ error: unknown; reasons: readonly string[] }> = [];
  owner.onDidChange((event) => {
    assert.ok(Object.isFrozen(event));
    assert.ok(Object.isFrozen(event.reasons));
    assert.equal(owner.getSnapshot(), event.snapshot);
    changed.push(event);
  });
  owner.onDidRefreshError((event) => {
    assert.ok(Object.isFrozen(event));
    assert.ok(Object.isFrozen(event.reasons));
    errors.push(event);
  });
  let started = false;
  const starting = owner.start().then(() => {
    started = true;
  });
  await flush();
  assert.equal(started, false);
  assert.equal(owner.getSnapshot(), null);
  assert.equal(inputs.length, 0);
  accounts.snapshot = Object.assign(account("synthetic-account:1"), { discarded: marker });
  accounts.emit("");
  await starting;
  const first = owner.getSnapshot()!;
  assert.equal(source.subscribeCount, 1);
  assert.equal(accounts.subscribeCount, 1);
  assert.equal(inputs.length, 1);
  assert.deepEqual(changed[0]?.reasons, ["account:changed"]);
  assert.equal(first.resolution, resolution);
  assert.notEqual(first.config, source.snapshot);
  assert.equal(first.config.knorviaBuiltinProviders, source.snapshot.knorviaBuiltinProviders);
  assert.equal("marker" in first.config && first.config.marker, marker);
  assert.equal("discarded" in first.account, false);
  assert.equal(first.account.states, accounts.snapshot.states);
  assert.ok(Object.isFrozen(first));
  assert.ok(Object.isFrozen(first.config));
  assert.ok(Object.isFrozen(first.account));
  assert.ok(Object.isFrozen(first.sourceRevisions));
  const readCount = source.readCount;
  await owner.start();
  assert.equal(source.readCount, readCount);
  assert.equal(await owner.refresh(), first);
  assert.equal(inputs.length, 1);
  accounts.snapshot = account("synthetic-account:mismatch", "synthetic-other");
  assert.equal(await owner.refresh("mismatch"), first);
  assert.equal(owner.getSnapshot(), first);
  assert.equal(changed.length, 1);

  accounts.snapshot = account("synthetic-account:2");
  source.snapshot = config("synthetic-config:2");
  const staleRead = deferred<ProviderConfigSnapshot>();
  const readEntered = deferred<void>();
  let useDeferred = true;
  source.readAction = () => {
    if (useDeferred) {
      useDeferred = false;
      readEntered.resolve(undefined);
      return staleRead.promise;
    }
    return Promise.resolve(source.snapshot);
  };
  const requestOne = owner.refresh("one");
  await readEntered.promise;
  const requestTwo = owner.refresh("two");
  const requestDuplicate = owner.refresh("one");
  assert.notEqual(requestOne, requestTwo);
  staleRead.resolve(config("synthetic-stale"));
  const fresh = await requestOne;
  assert.equal(await requestTwo, fresh);
  assert.equal(await requestDuplicate, fresh);
  assert.equal(fresh.sourceRevisions.config, "synthetic-config:2");
  assert.deepEqual(changed.at(-1)?.reasons, ["one", "two"]);
  assert.equal(inputs.length, 2);
  source.readAction = undefined;

  const sourceError = new Error("synthetic source failure");
  source.readAction = () => Promise.reject(sourceError);
  await assert.rejects(owner.refresh("failed-read"), (error: unknown) => error === sourceError);
  assert.equal(errors.at(-1)?.error, sourceError);
  assert.equal(owner.getSnapshot(), fresh);
  source.readAction = undefined;
  source.snapshot = config("synthetic-config:3");
  resolverFailure = new Error("synthetic resolver failure");
  await assert.rejects(
    owner.refresh("failed-resolution"),
    (error: unknown) => error === resolverFailure,
  );
  assert.equal(errors.at(-1)?.error, resolverFailure);
  assert.equal(owner.getSnapshot(), fresh);
  resolverFailure = undefined;
  const listenerFailure = new Error("synthetic observer failure");
  const removeThrower = owner.onDidChange(() => {
    throw listenerFailure;
  });
  const published = await owner.refresh("observer-failure");
  assert.notEqual(published, fresh);
  assert.equal(owner.getSnapshot(), published);
  assert.equal(errors.at(-1)?.error, listenerFailure);
  removeThrower();
  assert.deepEqual(owner.listProviders(), []);
  assert.equal(owner.getProvider("synthetic-absent"), undefined);
  assert.equal(owner.getModel("synthetic-absent", "synthetic-model"), undefined);
  assert.deepEqual(
    owner.validateSelection({ providerId: "synthetic-absent", modelId: "synthetic-model" }),
    {
      ok: false,
      code: "provider-not-found",
      providerId: "synthetic-absent",
    },
  );

  source.snapshot = config("synthetic-config:4");
  const disposalRead = deferred<ProviderConfigSnapshot>();
  source.readAction = () => disposalRead.promise;
  const pendingOne = owner.refresh("pending-one");
  const pendingTwo = owner.refresh("pending-two");
  const firstRejection = pendingOne.catch((error: unknown) => error);
  const secondRejection = pendingTwo.catch((error: unknown) => error);
  owner.dispose();
  owner.dispose();
  const disposalError = await firstRejection;
  assert.ok(disposalError instanceof Error);
  assert.equal(disposalError.message, "ProviderRegistryService 已 dispose");
  assert.equal(await secondRejection, disposalError);
  const eventCount = changed.length;
  disposalRead.resolve(source.snapshot);
  await flush();
  assert.equal(owner.getSnapshot(), published);
  assert.equal(changed.length, eventCount);
  assert.equal(source.disposeCount, 1);
  assert.equal(accounts.disposeCount, 1);
  assert.throws(() => owner.refresh(), /已 dispose/);
  await assert.rejects(owner.start(), /已 dispose/);
  owner.onDidChange(() => {})();
  owner.onDidRefreshError(() => {})();
});

